"""Normalization helpers for model names, scores, and timestamps."""

from __future__ import annotations

import re
from datetime import datetime, timezone

RFC3339_FMT = "%Y-%m-%dT%H:%M:%SZ"

_WS_RE = re.compile(r"[\s_]+")
_MULTI_DASH_RE = re.compile(r"-{2,}")
_US_TS_FMT = "%m/%d/%Y %H:%M"

# Epoch values at or above this are taken to be milliseconds. In seconds this
# threshold is roughly the year 5138, far past any plausible eval timestamp.
_EPOCH_MS_THRESHOLD = 100_000_000_000


def normalize_model(raw: str) -> str:
    """Canonical model name: lowercase, runs of whitespace/underscores -> '-'."""
    name = _WS_RE.sub("-", raw.strip().lower())
    name = _MULTI_DASH_RE.sub("-", name)
    return name.strip("-")


def _format_utc(dt: datetime) -> str:
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).strftime(RFC3339_FMT)


def parse_timestamp_mixed(text: str) -> str | None:
    """Parse Format A timestamps: ISO-8601 (with optional Z/offset) or
    US-style ``MM/DD/YYYY HH:MM``. Naive values are assumed UTC.
    Returns an RFC3339 string, or None if unparseable."""
    text = text.strip()
    if not text:
        return None
    try:
        return _format_utc(datetime.fromisoformat(text.replace("Z", "+00:00")))
    except ValueError:
        pass
    try:
        return _format_utc(datetime.strptime(text, _US_TS_FMT))
    except ValueError:
        return None


def epoch_to_rfc3339(ts: object) -> str | None:
    """Convert a unix epoch (seconds, or milliseconds when implausibly large)
    to an RFC3339 string. Returns None for non-numeric or out-of-range input."""
    if isinstance(ts, bool) or not isinstance(ts, (int, float)):
        return None
    value = float(ts)
    if abs(value) >= _EPOCH_MS_THRESHOLD:
        value /= 1000.0
    try:
        return _format_utc(datetime.fromtimestamp(value, tz=timezone.utc))
    except (OverflowError, OSError, ValueError):
        return None


def date_to_rfc3339(text: str) -> str | None:
    """Parse a bare ``YYYY-MM-DD`` date as midnight UTC."""
    try:
        return _format_utc(datetime.strptime(text.strip(), "%Y-%m-%d"))
    except ValueError:
        return None


def parse_score_text(text: str) -> float | None:
    """Parse a Format A score: either a percentage string ('87.5%') or a
    bare float. Returns the raw numeric value (percent already divided by
    100) without range clamping, or None if unparseable."""
    text = text.strip()
    if not text:
        return None
    if text.endswith("%"):
        try:
            return float(text[:-1].strip()) / 100.0
        except ValueError:
            return None
    try:
        return float(text)
    except ValueError:
        return None


def clamp_score(score: float) -> tuple[float, bool]:
    """Clamp a score into [0, 1]. Returns (score, was_clamped)."""
    if score < 0.0:
        return 0.0, True
    if score > 1.0:
        return 1.0, True
    return score, False

"""Command-line interface: ``evalmerge ingest <dir>`` and ``evalmerge report``."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from . import db
from .ingest import ingest
from .report import build_report

DEFAULT_DB = Path("evalmerge.db")


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="evalmerge",
        description="Normalize, deduplicate, and load model-evaluation results.",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    p_ingest = sub.add_parser(
        "ingest",
        help="discover harness_a/*.csv, harness_b/*.jsonl, harness_c/results.xml "
        "under DIRECTORY and upsert into the database",
    )
    p_ingest.add_argument("directory", type=Path, help="root directory of input files")
    p_ingest.add_argument(
        "--db", type=Path, default=DEFAULT_DB, help="SQLite database path (default: %(default)s)"
    )

    p_report = sub.add_parser("report", help="print a data-quality report")
    p_report.add_argument(
        "--db", type=Path, default=DEFAULT_DB, help="SQLite database path (default: %(default)s)"
    )
    return parser


def _cmd_ingest(args: argparse.Namespace) -> int:
    if not args.directory.is_dir():
        print(f"error: {args.directory} is not a directory", file=sys.stderr)
        return 2
    summary = ingest(args.directory, args.db)
    if summary.total_files == 0:
        print(f"error: no input files found under {args.directory}", file=sys.stderr)
        return 2
    print(f"Ingested into {args.db}")
    for source in ("a", "b", "c"):
        print(
            f"  source {source}: {summary.files.get(source, 0)} file(s), "
            f"{summary.ingested.get(source, 0)} row(s)"
        )
    print(f"  duplicate corrections applied: {summary.corrections}")
    if summary.skipped:
        for rule in sorted(summary.skipped):
            print(f"  skipped ({rule}): {summary.skipped[rule]}")
    return 0


def _cmd_report(args: argparse.Namespace) -> int:
    if not args.db.is_file():
        print(f"error: database {args.db} not found (run ingest first)", file=sys.stderr)
        return 2
    conn = db.connect(args.db)
    try:
        print(build_report(conn))
    finally:
        conn.close()
    return 0


def main(argv: list[str] | None = None) -> int:
    args = _build_parser().parse_args(argv)
    if args.command == "ingest":
        return _cmd_ingest(args)
    return _cmd_report(args)


if __name__ == "__main__":
    sys.exit(main())
